examples.template:
Row(
    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1),
    verticalAlignment = Alignment.CenterVertically,
) {
    MonarchText(text = {{prefix}})
    Box {
        MonarchLink(
            text = {{user.name}},
            onClick = { open = true },
            actionLabel = "show profile preview",
        )
        MonarchPopover(
            expanded = open,
            onDismissRequest = { open = false },
            label = "Profile of {{user.name|raw}}",
        ) {
            Row(
                horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                MonarchAvatar(
                    image = null,
                    name = {{user.name}},
                    size = MonarchAvatarSize.Lg,
                    status = MonarchPresenceStatus.{{user.status|pascal}},
                    seed = {{user.id}},
                )
                Column {
                    MonarchText(text = {{user.name}}, style = MonarchTextStyle.Subheading, heading = true)
                    MonarchText(text = "{{user.handle|raw}} · {{user.title|raw}}", style = MonarchTextStyle.Caption)
                    MonarchText(text = {{user.statusText}}, style = MonarchTextStyle.Caption)
                }
            }
            Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                MonarchButton(text = {{message}}, onClick = { open = false }, variant = MonarchButtonVariant.Primary, size = MonarchButtonSize.Sm)
                MonarchButton(
                    text = {{profile}},
                    onClick = { open = false },
                    variant = MonarchButtonVariant.Ghost,
                    size = MonarchButtonSize.Sm,
                )
            }
        }
    }
}

